}
map fold {
  root = this.string().lowercase().replace_all_many([
    "á", "a", "ä", "a", "č", "c", "ď", "d", "é", "e", "í", "i", "ĺ", "l", "ľ", "l", "ň", "n", "ó", "o",
    "ô", "o", "ŕ", "r", "š", "s", "ť", "t", "ú", "u", "ý", "y", "ž", "z", ".", ""
  ]).re_replace_all("\\s+", " ").trim()
}
map text {
  root = if this == null { "" } else { this.string().re_replace_all("\\s+", " ").trim() }
}
let rows = this.rows.or([]).map_each(r -> {
  "name": r.Name.apply("text"),
  "kind": r.Category.apply("text"),
  "note": r.Note.apply("text"),
  "near": r.Tourist_Spot_Availability.apply("text"),
  "places": r.Count_.or(null),
  "at": $placed.get(r.Name.apply("text").apply("fold").replace_all(".", "")).or(null)
})
map reason {
  root = if this.name == "" || this.at == null { "not placed" }
    else if this.at.index(1) < 16.93 || this.at.index(1) > 17.3 || this.at.index(0) < 47.99 || this.at.index(0) > 48.28 { "outside Bratislava" }
    else if this.places != null && (this.places.type() != "number" || this.places < 0 || this.places > 100) { "out of range" }
    else { null }
}
let marked = $rows.map_each(s -> s.assign({ "_drop": s.apply("reason"), "_id": "coach-stop-" + s.name.apply("fold").re_replace_all("[^a-z0-9]+", "-").trim("-") }))
let usable = $marked.filter(s -> s._drop == null)
let once = $usable.unique(s -> s._id)
let tally = $marked.filter(s -> s._drop != null).fold({}, item -> item.tally.assign({ item.value._drop: item.tally.get(item.value._drop).or(0) + 1 }))
let dups = $usable.length() - $once.length()
meta dropped = (if $dups > 0 { $tally.assign({ "duplicate": $dups }) } else { $tally }).format_json(no_indent: true)
meta kept = $once.length().string()
meta unplaced = $marked.filter(s -> s._drop == "not placed").map_each(s -> s.name).join(", ")
root = if $once.length() == 0 { throw("the coach stops list holds no usable stop: nothing is written") } else { $once }
